const $=s=>document.querySelector(s);
const demoRates=[['Purolator','Ground','2 business days','$18.42'],['UPS','Standard','2–3 business days','$19.06'],['FedEx','Ground','2 business days','$21.18'],['GLS','Parcel','1–2 business days','$22.34']];
function home(){return `<section class="hero"><div class="eyebrow">The smarter way to ship parcels</div><h1>Shipping,<br><em>optimized.</em></h1><p class="lead">Compare shipping options, choose the right service and manage every parcel from one fast workspace.</p><div class="quote-card"><div class="quote-grid"><div class="field"><label>From</label><input id="from" placeholder="L6T 4A8"></div><div class="field"><label>To</label><input id="to" placeholder="V6B 1A1"></div><div class="field"><label>Weight</label><input placeholder="8 lb"></div><div class="field"><label>Package</label><select><option>Box</option><option>Envelope</option></select></div><button class="acid" onclick="location.hash='quote'">Compare rates →</button></div></div></section><section class="section dark"><div class="eyebrow">One shipping command centre</div><h2>Less shipping admin.<br>More movement.</h2><div class="features"><div class="feature"><span class="num">01 / COMPARE</span><h3>Rates without the noise.</h3><p class="muted">Put services, transit times and prices side-by-side in seconds.</p></div><div class="feature"><span class="num">02 / SHIP</span><h3>Labels in a few clicks.</h3><p class="muted">Saved addresses, package presets and a checkout built for repeat shippers.</p></div><div class="feature"><span class="num">03 / CONTROL</span><h3>Everything accounted for.</h3><p class="muted">Shipments, tracking, billing and team activity live in one workspace.</p></div></div></section><section class="section"><div class="eyebrow">Built for Canadian businesses</div><h2>Every carrier.<br>One calculation.</h2><div class="stats"><div class="stat"><strong>1</strong><span>workspace for parcel operations</span></div><div class="stat"><strong>24/7</strong><span>shipment visibility</span></div><div class="stat"><strong>0</strong><span>spreadsheet gymnastics required</span></div></div></section>`}
function quote(){return shell('quote',`<div class="shipment-page"><div class="eyebrow">Create shipment</div><div class="ship-layout"><main class="ship-main"><div class="toolbar ship-title"><div><h1>Create a shipment.</h1><p class="muted">Enter sender, recipient and package details to compare services.</p></div></div><div class="shipment-sections"><div class="address-pair">${addressBlock('from','01','From','Sender address')}<div class="swap-bridge"><button class="swap-btn" onclick="swapAddresses()" title="Swap sender and recipient"><span>⇄</span><small>SWAP</small></button></div>${addressBlock('to','02','To','Recipient address')}</div><div class="form-card customs-card" id="customs-card" style="display:none"><div class="section-title"><span>03</span><div><h3>Customs & duties</h3><p class="muted">Required for international shipments</p></div><div class="intl-badge">INTERNATIONAL</div></div><div class="customs-alert"><strong>International destination detected</strong><span>Complete customs information for each item so duties, taxes and required documentation can be determined.</span></div><div id="customs-items"><div class="customs-item"><div class="customs-item-head"><strong>Item 1</strong><button class="ghost" onclick="removeCustomsItem(this)">Remove</button></div><div class="customs-grid"><div class="form-field customs-desc"><label>Detailed item description</label><input placeholder="e.g. Men's cotton t-shirt"></div><div class="form-field"><label>Quantity</label><input type="number" min="1" value="1"></div><div class="form-field"><label>Unit value</label><input type="number" min="0" step=".01" placeholder="25.00"></div><div class="form-field"><label>Currency</label><select><option>CAD</option><option>USD</option><option>EUR</option><option>GBP</option></select></div><div class="form-field hs-field"><label>HS code</label><div class="hs-input"><input placeholder="e.g. 6109.10"><button onclick="findHSCode(this)">Find HS code</button></div><small>6–10 digit tariff classification</small></div><div class="form-field"><label>Country of origin</label><select><option value="">Select country</option><option>Canada</option><option>United States</option><option>China</option><option>Italy</option><option>Greece</option><option>Mexico</option><option>United Kingdom</option><option>Germany</option><option>France</option><option>Japan</option></select></div><div class="form-field"><label>SKU / product reference</label><input placeholder="Optional"></div><div class="form-field"><label>Weight per unit</label><div class="input-unit"><input type="number" min="0" step=".01" placeholder="1"><select><option>lb</option><option>kg</option></select></div></div></div></div></div><button class="ghost add-customs-item" onclick="addCustomsItem()">+ Add another item</button><div class="customs-bottom"><div class="form-field"><label>Reason for export</label><select><option>Commercially sold goods</option><option>Gift</option><option>Returned goods</option><option>Repair / return</option><option>Personal effects</option><option>Sample</option><option>Other</option></select></div><div class="form-field"><label>Duties & taxes</label><select id="duties-party"><option>Bill to sender (DDP)</option><option>Bill to recipient (DAP/DDU where supported)</option></select></div><div class="form-field"><label>Tax ID type</label><select><option>None</option><option>IOSS</option><option>VAT</option><option>EORI</option><option>Other</option></select></div><div class="form-field"><label>Tax ID</label><input placeholder="Optional / destination dependent"></div></div><div class="duty-estimate"><div><span>Estimated duties & taxes</span><strong id="duty-total">Calculated with live carrier/customs rates</strong></div><button class="ghost" onclick="estimateDuties()">Estimate duties</button></div></div><div class="form-card" id="package-card"><div class="section-title"><span id="package-step-number">03</span><div><h3>Package</h3><p class="muted">Weight and dimensions</p></div></div><div class="package-grid"><div class="form-field"><label>Package type</label><select><option>Box</option><option>Envelope</option><option>Pak</option><option>Tube</option><option>Custom packaging</option></select></div><div class="form-field"><label>Weight</label><div class="input-unit"><input type="number" min="0" step=".1" placeholder="8"><select><option>lb</option><option>kg</option></select></div></div><div class="form-field"><label>Length</label><div class="input-unit"><input type="number" min="0" step=".1" placeholder="12"><select><option>in</option><option>cm</option></select></div></div><div class="form-field"><label>Width</label><div class="input-unit"><input type="number" min="0" step=".1" placeholder="10"><select><option>in</option><option>cm</option></select></div></div><div class="form-field"><label>Height</label><div class="input-unit"><input type="number" min="0" step=".1" placeholder="8"><select><option>in</option><option>cm</option></select></div></div><div class="form-field"><label>Quantity</label><input type="number" min="1" value="1"></div><div class="form-field package-contents"><label>Package contents</label><input placeholder="e.g. Apparel"></div><div class="form-field"><label>Declared value</label><div class="input-unit"><input type="number" min="0" step=".01" placeholder="100.00"><select><option>CAD</option><option>USD</option></select></div></div></div><button class="primary shipment-cta" onclick="showRates();setShipStep(4)">Compare shipping rates →</button><div id="ratebox"></div></div></div></main><aside class="ship-overview"><div class="overview-card"><div class="eyebrow">Shipment overview</div><h3>Your shipment</h3><div class="overview-route"><div><i>FROM</i><strong id="overview-from">Add sender</strong></div><span>→</span><div><i>TO</i><strong id="overview-to">Add recipient</strong></div></div><div class="ship-steps"><button data-ship-step="from" onclick="scrollShip('from-card')"><b>01</b><span><strong>Sender</strong><small>Origin address</small></span></button><button data-ship-step="to" onclick="scrollShip('to-card')"><b>02</b><span><strong>Recipient</strong><small>Destination address</small></span></button><button data-ship-step="customs" id="overview-customs-step" style="display:none" onclick="scrollShip('customs-card')"><b>03</b><span><strong>Customs</strong><small>HS codes & duties</small></span></button><button data-ship-step="package" onclick="scrollShip('package-card')"><b id="overview-package-num">03</b><span><strong>Package</strong><small>Weight & dimensions</small></span></button><button data-ship-step="rates" id="step-rates" onclick="document.getElementById('ratebox')?.scrollIntoView({behavior:'smooth',block:'center'})"><b id="overview-rates-num">04</b><span><strong>Rates</strong><small>Compare carriers</small></span></button><button data-ship-step="review"><b id="overview-review-num">05</b><span><strong>Review & pay</strong><small>Confirm shipment</small></span></button><button data-ship-step="label"><b id="overview-label-num">06</b><span><strong>Label</strong><small>Print & ship</small></span></button></div><div class="overview-summary"><div><span>Route</span><strong id="overview-route-status">Not complete</strong></div><div><span>Package</span><strong id="overview-package-status">Not entered</strong></div><div><span>Customs</span><strong id="overview-customs-status">Not required</strong></div></div><div class="overview-note">Complete each section to advance your shipment.</div></div></aside></div></div>`,true)}
function addressBlock(id,num,title,desc){return `<div class="form-card address-card" id="${id}-card" data-address="${id}"><div class="section-title address-heading"><span>${num}</span><div><h3>${title}</h3><p class="muted">${desc}</p></div><button class="address-book-btn" onclick="openAddressBook('${id}')">⌕ Address Book</button></div><div class="form-grid"><div class="form-field"><label>Contact name</label><input data-key="name" placeholder="Full name"></div><div class="form-field"><label>Company</label><input data-key="company" placeholder="Company name (optional)"></div><div class="form-field full"><label>Address</label><input data-key="address" placeholder="Street number and street name"></div><div class="form-field full"><label>Apartment, suite, unit, building</label><input data-key="unit" placeholder="Optional"></div><div class="form-field"><label>City</label><input data-key="city" placeholder="City"></div><div class="form-field"><label>Province / State</label><select data-key="province"></select></div><div class="form-field"><label>Postal / ZIP code</label><input data-key="postal" placeholder="A1A 1A1"></div><div class="form-field"><label>Country</label><select data-key="country" onchange="countryChanged(this)"><option>Canada</option><option>United States</option></select></div><div class="form-field"><label>Phone</label><input data-key="phone" placeholder="Phone number"></div><div class="form-field"><label>Email</label><input data-key="email" type="email" placeholder="name@company.com"></div></div><div class="address-options"><label><input type="checkbox" data-key="residential"> Residential Address</label><label><input type="checkbox" data-key="notifications"> Notifications</label><label><input type="checkbox" data-key="pobox"> P.O. Box</label><label><input type="checkbox" data-key="save"> Save to Address Book</label></div></div>`}
const demoAddresses=[{name:"Main Warehouse",company:"Demo Merchant Inc.",address:"14 Sigma Way",unit:"",city:"Brampton",province:"Ontario",postal:"L6T 4A8",country:"Canada",phone:"(905) 555-0188",email:"shipping@example.com"},{name:"West Coast Retail",company:"West Coast Retail",address:"1280 Homer St",unit:"Suite 200",city:"Vancouver",province:"British Columbia",postal:"V6B 2Y5",country:"Canada",phone:"(604) 555-0123",email:"receiving@example.com"},{name:"Montréal Wholesale",company:"Montréal Wholesale",address:"7250 Rue du Mile End",unit:"",city:"Montréal",province:"Quebec",postal:"H2R 3A4",country:"Canada",phone:"(514) 555-0192",email:"dock@example.com"}];
window.openAddressBook=id=>{document.querySelector('.address-modal')?.remove();let m=document.createElement('div');m.className='address-modal';m.innerHTML=`<div class="address-dialog"><div class="toolbar"><div><div class="eyebrow">Address book</div><h2>Select an address</h2></div><button class="ghost" id="close-address">Close</button></div><div class="address-choices">${demoAddresses.map((a,i)=>`<button onclick="selectAddress('${id}',${i})"><strong>${a.name}</strong><span>${a.address}, ${a.city}, ${a.province} ${a.postal}</span></button>`).join('')}</div><button class="primary" data-route="addresses">Manage address book</button></div>`;document.body.appendChild(m);m.querySelector('#close-address').onclick=()=>m.remove();m.addEventListener('click',e=>{if(e.target===m)m.remove()})}
const regions={Canada:["Alberta","British Columbia","Manitoba","New Brunswick","Newfoundland and Labrador","Northwest Territories","Nova Scotia","Nunavut","Ontario","Prince Edward Island","Quebec","Saskatchewan","Yukon"],"United States":["Alabama","Alaska","Arizona","Arkansas","California","Colorado","Connecticut","Delaware","Florida","Georgia","Hawaii","Idaho","Illinois","Indiana","Iowa","Kansas","Kentucky","Louisiana","Maine","Maryland","Massachusetts","Michigan","Minnesota","Mississippi","Missouri","Montana","Nebraska","Nevada","New Hampshire","New Jersey","New Mexico","New York","North Carolina","North Dakota","Ohio","Oklahoma","Oregon","Pennsylvania","Rhode Island","South Carolina","South Dakota","Tennessee","Texas","Utah","Vermont","Virginia","Washington","West Virginia","Wisconsin","Wyoming","District of Columbia"]};
window.setRegions=(card,value)=>{let country=card.querySelector('[data-key="country"]')?.value,sel=card.querySelector('[data-key="province"]'),list=regions[country]||[];if(!sel)return;sel.innerHTML=list.map(x=>'<option>'+x+'</option>').join('');if(value&&list.includes(value))sel.value=value}
window.countryChanged=el=>{let card=el.closest('.address-card');setRegions(card);updateOverview()}
window.selectAddress=(id,i)=>{let card=document.querySelector('[data-address="'+id+'"]'),a=demoAddresses[i];let country=card.querySelector('[data-key="country"]');if(country)country.value=a.country;setRegions(card,a.province);Object.entries(a).forEach(([k,v])=>{if(k==='province'||k==='country')return;let el=card.querySelector('[data-key="'+k+'"]');if(el)el.value=v});document.querySelector('.address-modal')?.remove();updateOverview()}
window.swapAddresses=()=>{let a=document.querySelector('[data-address="from"]'),b=document.querySelector('[data-address="to"]'),keys=['name','company','address','unit','city','postal','phone','email','residential','notifications','pobox','save'],ac=a.querySelector('[data-key="country"]').value,bc=b.querySelector('[data-key="country"]').value,ap=a.querySelector('[data-key="province"]').value,bp=b.querySelector('[data-key="province"]').value;keys.forEach(k=>{let x=a.querySelector('[data-key="'+k+'"]'),y=b.querySelector('[data-key="'+k+'"]');if(!x||!y)return;if(x.type==='checkbox'){let t=x.checked;x.checked=y.checked;y.checked=t}else{let t=x.value;x.value=y.value;y.value=t}});a.querySelector('[data-key="country"]').value=bc;b.querySelector('[data-key="country"]').value=ac;setRegions(a,bp);setRegions(b,ap);updateOverview()}
window.updateOverview=()=>{['from','to'].forEach(id=>{let c=document.querySelector('[data-address="'+id+'"]'),city=c?.querySelector('[data-key="city"]')?.value,postal=c?.querySelector('[data-key="postal"]')?.value,name=c?.querySelector('[data-key="company"]')?.value||c?.querySelector('[data-key="name"]')?.value;let out=document.querySelector('#overview-'+id);if(out)out.textContent=[name,city,postal].filter(Boolean).join(' · ')||('Add '+(id==='from'?'sender':'recipient'))});detectInternational();refreshShipmentOverview()}
window.detectInternational=()=>{let to=document.querySelector('[data-address="to"]'),from=document.querySelector('[data-address="from"]');if(!to||!from)return;let fc=from.querySelector('[data-key="country"]')?.value,tc=to.querySelector('[data-key="country"]')?.value,postal=to.querySelector('[data-key="postal"]')?.value.trim(),intl=!!postal&&fc&&tc&&fc!==tc;let card=document.querySelector('#customs-card'),step=document.querySelector('#overview-customs-step');if(card)card.style.display=intl?'block':'none';if(step)step.style.display=intl?'grid':'none';[['package-step-number',intl?'04':'03'],['overview-package-num',intl?'04':'03'],['overview-rates-num',intl?'05':'04'],['overview-review-num',intl?'06':'05'],['overview-label-num',intl?'07':'06']].forEach(([id,v])=>{let e=document.getElementById(id);if(e)e.textContent=v})}
window.addCustomsItem=()=>{let wrap=document.querySelector('#customs-items'),base=wrap?.querySelector('.customs-item');if(!wrap||!base)return;let n=base.cloneNode(true);n.querySelectorAll('input').forEach(x=>x.value=x.type==='number'&&x.min==='1'?'1':'');n.querySelectorAll('select').forEach(x=>x.selectedIndex=0);wrap.appendChild(n);renumberCustomsItems()}
window.removeCustomsItem=btn=>{let items=document.querySelectorAll('.customs-item');if(items.length<=1)return;btn.closest('.customs-item')?.remove();renumberCustomsItems()}
window.renumberCustomsItems=()=>document.querySelectorAll('.customs-item').forEach((x,i)=>x.querySelector('.customs-item-head strong').textContent='Item '+(i+1));
window.findHSCode=btn=>{let input=btn.closest('.hs-input').querySelector('input'),desc=btn.closest('.customs-item').querySelector('.customs-desc input').value;input.placeholder=desc?'Search classification for “'+desc+'”':'Enter description first';input.focus()}
window.estimateDuties=()=>{let out=document.querySelector('#duty-total');if(out)out.textContent='Duty estimate requires tariff/API data at backend integration'}
window.scrollShip=id=>document.getElementById(id)?.scrollIntoView({behavior:'smooth',block:'start'});
window.setShipStep=n=>refreshShipmentOverview(n)
window.refreshShipmentOverview=forced=>{let req=id=>{let card=document.querySelector('[data-address="'+id+'"]');if(!card)return false;return ['name','address','city','province','postal','country','phone'].every(k=>card.querySelector('[data-key="'+k+'"]')?.value.trim())},from=req('from'),to=req('to'),intl=document.querySelector('#customs-card')?.style.display!=='none',pkg=document.querySelector('#package-card'),nums=pkg?[...pkg.querySelectorAll('input[type="number"]')].slice(0,4):[],packageDone=nums.length>=4&&nums.every(x=>Number(x.value)>0),customsDone=!intl||[...document.querySelectorAll('#customs-items .customs-item')].every(item=>{let desc=item.querySelector('.customs-desc input')?.value.trim(),hs=item.querySelector('.hs-field input')?.value.trim(),origin=item.querySelector('.customs-grid select:nth-of-type(2)')?.value;return !!(desc&&hs&&origin)}),ratesShown=!!document.querySelector('#ratebox')?.textContent.trim(),steps=[['from',from],['to',to],['customs',customsDone],['package',packageDone],['rates',ratesShown],['review',false],['label',false]];steps.forEach(([key,done])=>{let b=document.querySelector('[data-ship-step="'+key+'"]');if(!b)return;b.classList.toggle('done',done);b.classList.remove('active')});let current=!from?'from':!to?'to':intl&&!customsDone?'customs':!packageDone?'package':!ratesShown?'rates':'review';document.querySelector('[data-ship-step="'+current+'"]')?.classList.add('active');let route=document.querySelector('#overview-route-status'),ps=document.querySelector('#overview-package-status'),cs=document.querySelector('#overview-customs-status');if(route)route.textContent=from&&to?'Ready':'Not complete';if(ps)ps.textContent=packageDone?'Ready':'Not entered';if(cs)cs.textContent=intl?(customsDone?'Ready':'Required'):'Not required'}

window.showRates=()=>{$('#ratebox').innerHTML='<div class="rates">'+demoRates.map((r,i)=>`<div class="rate ${i===0?'best':''}"><strong>${r[0]}<br><small class="muted">${r[1]}</small></strong><span>${r[2]}</span><strong>${r[3]}</strong><button class="primary" onclick="location.hash='checkout'">Select</button></div>`).join('')+'</div>'}
const portalNav=[
 {label:'Shipping',items:[['quote','Ship'],['quick-quote','Quote Shipment'],['saved-quotes','Saved Quotes']]},
 {label:'Tracking',items:[['tracking','Tracking']]},
 {label:'Pick Ups',items:[['pickups','Pick Ups']]},
 {label:'E-Commerce',items:[['orders','Orders'],['products','Products'],['store-settings','Store Settings']]},
 {label:'Settings',items:[['packages','Package Manager'],['addresses','Address Book'],['carrier-accounts','Carrier Accounts'],['default-settings','Default Settings']]},
 {label:'Support',items:[['claims','Claims'],['tickets','Tickets']]}
];
function shell(active,content,wide=false){return `<div class="portal-shell"><aside class="portal-sidebar"><a class="portal-brand" href="#quote"><span class="sigma">Σ</span><span>SigmaShip</span></a><nav class="portal-nav">${portalNav.map(g=>`<div class="nav-group"><div class="nav-group-title">${g.label}</div>${g.items.map(([r,l])=>`<button class="${active===r?'active':''}" data-route="${r}">${l}</button>`).join('')}</div>`).join('')}</nav><div class="portal-help"><span>Need help?</span><button data-route="tickets">Contact support →</button></div></aside><div class="portal-stage"><header class="portal-top"><div><span class="portal-context">CUSTOMER PORTAL</span></div><div class="user-menu-wrap"><button class="user-trigger" onclick="toggleUserMenu(event)"><span class="user-avatar">VK</span><span class="user-copy"><strong>Demo Merchant Inc.</strong><small>Account</small></span><span>⌄</span></button><div class="user-dropdown" id="user-dropdown"><button data-route="profile">Profile</button><button data-route="accounting">Accounting</button><hr><button onclick="logoutDemo()">Logout</button></div></div></header><section class="portal-workspace ${wide?'wide':''}">${content}</section></div></div>`}
window.toggleUserMenu=e=>{e?.stopPropagation();document.getElementById('user-dropdown')?.classList.toggle('open')}
window.logoutDemo=()=>{location.hash='login'}
document.addEventListener('click',()=>document.getElementById('user-dropdown')?.classList.remove('open'))

function quickQuote(){return shell('quick-quote',`<div class="eyebrow">Shipping / Quote Shipment</div><div class="toolbar"><div><h1>Quick quote</h1><span class="muted">Get an estimated shipping rate with only the essentials.</span></div><button class="ghost" data-route="saved-quotes">Saved quotes</button></div><div class="quick-quote-layout"><div class="form-card"><div class="form-grid"><div class="form-field"><label>Ship from postal / ZIP</label><input placeholder="L6T 4A8"></div><div class="form-field"><label>Ship to postal / ZIP</label><input placeholder="V6B 1A1"></div><div class="form-field"><label>Weight</label><div class="input-unit"><input type="number" placeholder="8"><select><option>lb</option><option>kg</option></select></div></div><div class="form-field"><label>Package type</label><select><option>Box</option><option>Envelope</option><option>Pak</option></select></div><div class="form-field"><label>Length</label><input type="number" placeholder="12"></div><div class="form-field"><label>Width</label><input type="number" placeholder="10"></div><div class="form-field"><label>Height</label><input type="number" placeholder="8"></div><div class="form-field"><label>Units</label><select><option>in</option><option>cm</option></select></div></div><div class="quote-actions"><button class="ghost" onclick="alert('Quote saved to Saved Quotes in the prototype.')">Save quote</button><button class="primary" onclick="quickQuoteRates()">Get quote →</button></div></div><div class="quote-side"><div class="eyebrow">HOW IT WORKS</div><h3>Quote now. Finish later.</h3><p class="muted">Use postal codes, weight and dimensions for a fast estimate. When you're ready to buy, SigmaShip carries the quote into Ship so you can add full addresses, customs details and payment.</p><div class="mini-flow"><b>01 Quote</b><span>02 Select rate</span><span>03 Complete shipment</span><span>04 Buy label</span></div></div></div><div id="quick-ratebox"></div>`)}
window.quickQuoteRates=()=>{let el=document.getElementById('quick-ratebox');if(el)el.innerHTML=`<div class="table"><div class="row head"><span>Carrier</span><span>Service</span><span>Transit</span><span>Estimate</span><span></span></div>${demoRates.map(r=>`<div class="row"><strong>${r[0]}</strong><span>${r[1]}</span><span>${r[2]}</span><strong>${r[3]}</strong><button class="small-btn" data-route="quote">Continue →</button></div>`).join('')}</div>`;document.querySelectorAll('[data-route]').forEach(x=>x.onclick=()=>location.hash=x.dataset.route)}
function savedQuotes(){return shell('saved-quotes',`<div class="eyebrow">Shipping / Saved Quotes</div><div class="toolbar"><div><h1>Saved quotes</h1><span class="muted">Return to estimates you've saved but haven't purchased.</span></div><button class="primary" data-route="quick-quote">+ New quote</button></div><div class="filterbar"><input placeholder="Search quote, destination or postal code"><select><option>All quotes</option><option>Active</option><option>Expired</option></select></div><div class="table quote-table"><div class="row head"><span>Quote</span><span>Route</span><span>Package</span><span>Best rate</span><span>Status</span></div><div class="row"><strong>SQ-2084</strong><span>Brampton → Vancouver</span><span>8 lb · 12×10×8</span><span>$18.42</span><button class="small-btn" data-route="quote">Complete shipment</button></div><div class="row"><strong>SQ-2083</strong><span>Brampton → Calgary</span><span>4 lb · 10×8×6</span><span>$16.80</span><span class="badge">Saved</span></div></div>`)}
function products(){return shell('products',`<div class="eyebrow">E-Commerce / Products</div><div class="toolbar"><div><h1>Products</h1><span class="muted">Synced product data used to automate package and customs information.</span></div><button class="primary">+ Add product</button></div><div class="filterbar"><input placeholder="Search SKU or product"><select><option>All stores</option><option>Shopify</option><option>WooCommerce</option></select></div><div class="table"><div class="row head"><span>Product</span><span>SKU</span><span>Weight</span><span>HS code</span><span>Origin</span></div><div class="row"><strong>Estate Bottle</strong><span>AE-750</span><span>3.2 lb</span><span>1509.10</span><span>Greece</span></div><div class="row"><strong>Pour Spout</strong><span>AE-PS01</span><span>0.2 lb</span><span>3924.10</span><span>Canada</span></div></div>`)}
function storeSettings(){return shell('store-settings',`<div class="eyebrow">E-Commerce / Store Settings</div><div class="toolbar"><div><h1>Store settings</h1><span class="muted">Connect sales channels and control how orders flow into SigmaShip.</span></div><button class="primary" onclick="integrationDemo('Store')">+ Connect store</button></div><div class="store-grid"><div class="store-card connected"><div class="store-mark">S</div><div><span class="status-dot">CONNECTED</span><h3>Shopify</h3><p class="muted">Ana's Estate · Orders and fulfillment syncing</p></div><button class="ghost">Manage</button></div><div class="store-card"><div class="store-mark">W</div><div><span class="status-dot off">NOT CONNECTED</span><h3>WooCommerce</h3><p class="muted">Import orders and sync tracking back automatically.</p></div><button class="ghost" onclick="integrationDemo('WooCommerce')">Connect</button></div></div><div class="settings-grid"><div class="card"><h3>Order import</h3><p class="muted">Automatically import paid, unfulfilled orders.</p><label class="switch-row"><span>Auto import orders</span><input type="checkbox" checked></label></div><div class="card"><h3>Fulfillment sync</h3><p class="muted">Send carrier and tracking details back after label purchase.</p><label class="switch-row"><span>Sync tracking</span><input type="checkbox" checked></label></div></div>`)}
function carrierAccounts(){return shell('carrier-accounts',`<div class="eyebrow">Settings / Carrier Accounts</div><div class="toolbar"><div><h1>Carrier accounts</h1><span class="muted">Use your own negotiated carrier rates through SigmaShip.</span></div><button class="primary" onclick="addCarrierAccount()">+ Connect carrier account</button></div><div class="notice"><strong>Bring your own account</strong><br>Ship on your own carrier contract while using SigmaShip to quote, create labels, track shipments and manage orders. A SigmaShip processing fee applies to labels purchased using a connected carrier account.</div><div class="kpis"><div class="kpi"><small>Connected</small><strong id="carrier-connected-count">0</strong></div><div class="kpi"><small>Active</small><strong id="carrier-active-count">0</strong></div><div class="kpi"><small>BYOA fee</small><strong>$1.00</strong><span class="muted">demo / label</span></div></div><div id="carrier-account-list" class="list-cards"></div><div class="settings-grid"><div class="card"><h3>Rate preference</h3><p class="muted">Choose how your own rates compete with SigmaShip rates.</p><div class="form-field"><label>Default rate source</label><select onchange="saveCarrierPreference(this.value)"><option value="best">Show both · choose best price</option><option value="own">Prefer my carrier accounts</option><option value="sigma">Prefer SigmaShip rates</option></select></div></div><div class="card"><h3>How billing works</h3><p class="muted">Carrier transportation charges are billed according to your carrier agreement. SigmaShip separately charges the displayed platform/processing fee for labels created through your connected account.</p></div></div>`)}
window.addCarrierAccount=()=>ssModal('Connect carrier account',`<div class="form-grid"><div class="form-field"><label>Carrier</label><select name="carrier" required><option>UPS</option><option>FedEx</option><option>Purolator</option><option>Canada Post</option><option>GLS</option><option>DHL Express</option></select></div>${ssField('Account nickname','nickname','text','','placeholder="My UPS account"')}${ssField('Carrier account number','account','text','','required')}<div class="form-field"><label>Connection method</label><select name="method"><option>API / OAuth credentials</option><option>Account number + credentials</option></select></div></div><div class="notice">For production, secrets will be encrypted and stored in a secure credential vault. They will never be exposed back to the browser after connection.</div>`,'Connect account',d=>{let s=ssLoad();s.carrierAccounts=s.carrierAccounts||[];s.carrierAccounts.push({id:'CA-'+Date.now(),carrier:d.carrier,nickname:d.nickname||d.carrier,accountLast4:d.account.slice(-4),method:d.method,status:'Pending verification',active:true});ssSave(s);ssToast(d.carrier+' account added for verification.');render()})
window.saveCarrierPreference=v=>{let s=ssLoad();s.carrierPreference=v;ssSave(s);ssToast('Carrier rate preference saved.')}
function enhanceCarrierAccounts(){if(location.hash!=='#carrier-accounts')return;let s=ssLoad(),arr=s.carrierAccounts||[],wrap=document.getElementById('carrier-account-list');let cc=document.getElementById('carrier-connected-count'),ac=document.getElementById('carrier-active-count');if(cc)cc.textContent=arr.length;if(ac)ac.textContent=arr.filter(x=>x.active).length;let sel=document.querySelector('[onchange*="saveCarrierPreference"]');if(sel)sel.value=s.carrierPreference||'best';if(!arr.length&&wrap)wrap.innerHTML='<div class="empty-state"><strong>No carrier accounts connected.</strong><span>Add an account to compare your negotiated rates against SigmaShip rates.</span></div>';arr.forEach((x,i)=>{let d=document.createElement('div');d.className='card carrier-account-card';d.innerHTML=`<div class="carrier-logo">${x.carrier.slice(0,2).toUpperCase()}</div><div><span class="status-dot ${x.status==='Active'?'':'off'}">${x.status.toUpperCase()}</span><h3>${x.nickname}</h3><p class="muted">${x.carrier} · Account •••• ${x.accountLast4}</p></div><label class="carrier-toggle"><input type="checkbox" ${x.active?'checked':''}><span>Use for rates</span></label><button class="ghost carrier-verify">Verify</button><button class="ghost carrier-remove">Remove</button>`;d.querySelector('.carrier-toggle input').onchange=e=>{let n=ssLoad();n.carrierAccounts[i].active=e.target.checked;ssSave(n);ssToast(e.target.checked?'Carrier account enabled.':'Carrier account disabled.');enhanceCarrierAccounts()};d.querySelector('.carrier-verify').onclick=()=>{let n=ssLoad();n.carrierAccounts[i].status='Active';ssSave(n);ssToast('Demo verification completed.');render()};d.querySelector('.carrier-remove').onclick=()=>ssConfirm('Remove this carrier account?',()=>{let n=ssLoad();n.carrierAccounts.splice(i,1);ssSave(n);render()});wrap?.appendChild(d)})}
function defaultSettings(){return shell('default-settings',`<div class="eyebrow">Settings / Default Settings</div><div class="toolbar"><div><h1>Default settings</h1><span class="muted">Pre-fill repetitive shipping choices across your account.</span></div><button class="primary">Save changes</button></div><div class="settings-grid"><div class="card"><h3>Shipment defaults</h3><div class="form-field"><label>Default sender</label><select><option>Main Warehouse · Brampton</option></select></div><div class="form-field"><label>Default package</label><select><option>No default</option><option>Small carton</option></select></div></div><div class="card"><h3>Units & currency</h3><div class="form-field"><label>Measurement system</label><select><option>Imperial · lb / in</option><option>Metric · kg / cm</option></select></div><div class="form-field"><label>Currency</label><select><option>CAD</option><option>USD</option></select></div></div><div class="card"><h3>Shipment options</h3>${toggles(['Residential address by default','Email shipment notifications','Require signature','Add declared value coverage'])}</div><div class="card"><h3>Printing</h3><div class="form-field"><label>Label format</label><select><option>4 × 6 thermal</option><option>8.5 × 11 letter</option></select></div></div></div>`)}
function tickets(){return shell('tickets',`<div class="eyebrow">Support / Tickets</div><div class="toolbar"><div><h1>Support tickets</h1><span class="muted">Questions, billing issues and technical support in one thread.</span></div><button class="primary" onclick="alert('New ticket composer will connect to the support backend.')">+ New ticket</button></div><div class="kpis"><div class="kpi"><small>Open</small><strong>2</strong></div><div class="kpi"><small>Waiting on you</small><strong>1</strong></div><div class="kpi"><small>Resolved</small><strong>14</strong></div></div><div class="table"><div class="row head"><span>Ticket</span><span>Subject</span><span>Updated</span><span>Status</span><span></span></div><div class="row"><strong>#T-1042</strong><span>Carrier adjustment question</span><span>Today · 8:42 AM</span><span class="badge">Open</span><button class="small-btn">View</button></div><div class="row"><strong>#T-1038</strong><span>Shopify order sync</span><span>Oct 05</span><span>Resolved</span><button class="small-btn">View</button></div></div>`)}
function accounting(){return shell('accounting',`<div class="eyebrow">Account / Accounting</div><div class="toolbar"><div><h1>Accounting</h1><span class="muted">Payment methods, charges, invoices and account balance.</span></div><button class="primary" onclick="alert('Production card collection will use a PCI-compliant payment processor and tokenization.')">+ Add payment method</button></div><div class="accounting-grid"><div class="card payment-status"><span class="status-dot">PAYMENT READY</span><h3>Visa ending in 4242</h3><p class="muted">Default payment method · Expires 12/29</p><button class="ghost">Manage payment methods</button></div><div class="kpi"><small>Current month</small><strong>$2,418.16</strong><span class="muted">128 shipment charges</span></div><div class="kpi"><small>Account balance</small><strong>$0.00</strong><span class="muted">Nothing due</span></div></div><div class="subnav"><button class="active">Transactions</button><button data-route="invoices">Invoices</button></div><div class="table"><div class="row head"><span>Date</span><span>Reference</span><span>Description</span><span>Status</span><span>Amount</span></div><div class="row"><span>Oct 07</span><strong>SS-10482</strong><span>Purolator Ground</span><span class="badge">Paid</span><strong>$18.42</strong></div><div class="row"><span>Oct 07</span><strong>SS-10481</strong><span>UPS Standard</span><span class="badge">Paid</span><strong>$16.90</strong></div></div>`)}
function dashboard(){return shell('dashboard',`<div class="eyebrow">Workspace / Overview</div><div class="toolbar"><div><h1>Good morning.</h1><span class="muted">Here’s what’s moving.</span></div><button class="primary" data-route="quote">+ New shipment</button></div><div class="kpis"><div class="kpi"><small>Shipments / 30d</small><strong>128</strong></div><div class="kpi"><small>In transit</small><strong>19</strong></div><div class="kpi"><small>Delivered</small><strong>103</strong></div><div class="kpi"><small>Spend / 30d</small><strong>$2,418</strong></div></div>${shipmentTable()}`)}
