function billing(){return shell('billing',`<div class="eyebrow">Account / Billing</div><div class="toolbar"><div><h1>Billing</h1><span class="muted">Payment methods, transactions and invoices.</span></div><button class="primary" onclick="alert('Connect Stripe or another PCI-compliant processor before collecting real card details.')">+ Add payment method</button></div><div class="notice"><strong>Secure card architecture:</strong> SigmaShip will store processor tokens and card display metadata only. Raw card numbers and CVVs will not be stored by SigmaShip.</div><h3>Payment methods</h3><div class="payment-card"><span>DEFAULT</span><strong style="font-size:22px">•••• •••• •••• 4242</strong><div><span>VISA</span><span style="float:right">12 / 29</span></div></div><h3 style="margin-top:40px">Recent transactions</h3>${shipmentTable()}`)}
