function orders(){return shell('orders',`<div class="eyebrow">Commerce / Orders</div><div class="toolbar"><div><h1>Orders</h1><span class="muted">Orders from every connected storefront, ready to ship.</span></div><button class="primary" data-route="integrations">Connect a store</button></div><div class="kpis"><div class="kpi"><small>Ready to ship</small><strong>24</strong></div><div class="kpi"><small>On hold</small><strong>3</strong></div><div class="kpi"><small>Shipped today</small><strong>17</strong></div><div class="kpi"><small>Stores</small><strong>2</strong></div></div><div class="table"><div class="row head"><span>Order</span><span>Customer</span><span>Store</span><span>Status</span><span>Total</span></div><div class="row"><strong><a href="#order-detail">#1842</a></strong><span>Alex Morgan</span><span>Shopify</span><span><b class="badge">Ready</b></span><span>$129.00</span></div><div class="row"><strong>#1841</strong><span>Jamie Lee</span><span>WooCommerce</span><span><b class="badge">Ready</b></span><span>$84.50</span></div></div><div class="notice"><strong>Unified order workflow:</strong> select imported orders, verify package details, compare SigmaShip rates, purchase labels, then sync carrier and tracking information back to the originating store.</div>`)}
function integrations(){return shell('integrations',`<div class="eyebrow">Commerce / Integrations</div><div class="toolbar"><div><h1>Connected stores</h1><span class="muted">Bring orders into SigmaShip automatically.</span></div></div><div class="features"><div class="card"><div class="eyebrow">ECOMMERCE</div><h2 style="font-size:30px;margin:20px 0">Shopify</h2><p class="muted">Import orders and shipping details, then send fulfillment and tracking updates back.</p><button class="primary" onclick="integrationDemo('Shopify')">Connect Shopify</button></div><div class="card"><div class="eyebrow">ECOMMERCE</div><h2 style="font-size:30px;margin:20px 0">WooCommerce</h2><p class="muted">Sync orders through WooCommerce REST APIs and receive order changes with signed webhooks.</p><button class="primary" onclick="integrationDemo('WooCommerce')">Connect WooCommerce</button></div><div class="card"><div class="eyebrow">COMING NEXT</div><h2 style="font-size:30px;margin:20px 0">More channels</h2><p class="muted">Additional marketplaces and commerce platforms can plug into the same normalized order pipeline.</p><button class="ghost" disabled>Coming soon</button></div></div><div class="notice"><strong>Data permissions:</strong> store owners authorize each connection. SigmaShip should request only data required for shipping/order management, encrypt credentials and tokens, log access, support disconnect/deletion, and disclose any analytics use separately.</div>`)}
