function toggles(items){return `<div class="list-cards">${items.map((x,i)=>`<div class="card list-card"><strong>${x}</strong><span class="muted">Email and in-app</span><label class="switch"><input type="checkbox" ${i<4?'checked':''}><i></i></label></div>`).join('')}</div>`}

function bulk(){return shell('bulk',`<div class="eyebrow">Shipping / Bulk</div><div class="toolbar"><div><h1>Bulk shipping</h1><span class="muted">Create many shipments from orders or a CSV.</span></div><button class="primary">Upload CSV</button></div><div class="settings-grid"><div class="card"><h3>Import a file</h3><p class="muted">Upload a shipment CSV, map columns, validate addresses and compare rates in bulk.</p><button class="ghost">Choose CSV</button></div><div class="card"><h3>Ship store orders</h3><p class="muted">Select unfulfilled orders from all connected stores and process them together.</p><button class="ghost" data-route="orders">Choose orders</button></div></div>`)}
function manifests(){return shell('manifests',pageHead('Manifests','Close out carrier shipments and print end-of-day documents.','Create manifest')+cards([['MAN-10028','Oct 07 · Purolator · 18 shipments','Closed'],['MAN-10027','Oct 07 · UPS · 11 shipments','Closed'],['Open shipments','Today · 7 shipments','Not manifested']]))}
function claims(){return shell('claims',pageHead('Claims','Track lost, damaged and service-related claims.','+ New claim')+cards([['CLM-2041','SS-10392 · Damage · $184.00','Under review'],['CLM-2038','SS-10284 · Lost parcel · $92.00','Approved']]))}
function reports(){return shell('reports',`<div class="eyebrow">Analytics / Reports</div><div class="toolbar"><div><h1>Shipping intelligence</h1><span class="muted">Understand spend, volume, service and delivery performance.</span></div><button class="primary">Export report</button></div><div class="kpis"><div class="kpi"><small>Avg. cost</small><strong>$18.89</strong></div><div class="kpi"><small>On-time</small><strong>96.8%</strong></div><div class="kpi"><small>Avg. weight</small><strong>6.4 lb</strong></div><div class="kpi"><small>Exceptions</small><strong>2.1%</strong></div></div><div class="settings-grid"><div class="card"><h3>Spend by carrier</h3><div class="bars"><i style="width:82%"></i><i style="width:64%"></i><i style="width:47%"></i><i style="width:31%"></i></div></div><div class="card"><h3>Volume by service</h3><p class="metric">Ground <b>68%</b></p><p class="metric">Express <b>21%</b></p><p class="metric">Other <b>11%</b></p></div></div>`)}
function storeDetail(){return shell('integrations',`<div class="eyebrow">Integrations / Store</div><div class="toolbar"><div><h1>North Store</h1><span class="muted">Shopify · Connected</span></div><button class="ghost">Disconnect</button></div><div class="kpis"><div class="kpi"><small>Orders synced</small><strong>842</strong></div><div class="kpi"><small>Ready</small><strong>24</strong></div><div class="kpi"><small>Last sync</small><strong>2m</strong></div><div class="kpi"><small>Errors</small><strong>0</strong></div></div><div class="settings-grid"><div class="card"><h3>Sync settings</h3><p class="muted">Import paid orders automatically · Push tracking after shipment · Sync cancellations.</p><button class="ghost">Edit settings</button></div><div class="card"><h3>Data access</h3><p class="muted">Orders, fulfillment details and shipping addresses required for the shipping workflow.</p><button class="ghost">View permissions</button></div></div>`)}
function forgot(){return `<section class="page"><div class="eyebrow">Account recovery</div><h1>Reset your password.</h1><div class="form-card" style="max-width:520px"><div class="form-field"><label>Email</label><input type="email" placeholder="you@company.com"></div><button class="primary" style="margin-top:20px">Send reset link</button></div></section>`}
function pricing(){return `<section class="page"><div class="eyebrow">SigmaShip / Pricing</div><h1>Built to ship more.</h1><p class="lead">No complicated shipping software tiers in this prototype. Your shipping costs are shown before you buy.</p><div class="settings-grid" style="max-width:900px"><div class="card"><h3>Pay as you ship</h3><p class="muted">Compare available services and pay for labels as they are created.</p><strong>No platform fee shown</strong></div><div class="card"><h3>High-volume shipping</h3><p class="muted">Account-specific pricing and commercial programs can be represented here.</p><button class="primary">Contact sales</button></div></div></section>`}
function adminPage(kind){const names={customers:'Customers',shipments:'Shipments',orders:'Orders',pricingadmin:'Pricing rules',billingadmin:'Billing',adjustments:'Adjustments',supportadmin:'Support queue'};let title=names[kind]||'Operations';return `<div class="admin-shell"><aside class="adminbar"><div class="brand"><span class="sigma">Σ</span>Admin</div>${Object.entries(names).map(([k,v])=>`<button class="${kind===k?'active':''}" data-route="admin-${k}">${v}</button>`).join('')}<button data-route="admin">Overview</button></aside><section class="workspace"><div class="eyebrow">Admin / ${title}</div><div class="toolbar"><div><h1>${title}</h1><span class="muted">SigmaShip operations workspace.</span></div><button class="primary">+ New</button></div>${kind==='pricingadmin'?cards([['Standard SMB','Cost + 18%','184 accounts'],['Growth','Cost + 14%','92 accounts'],['Enterprise','Custom rules','42 accounts']]):kind==='adjustments'?cards([['ADJ-8821','SS-10402 · Reweigh +3 lb','+$4.28'],['ADJ-8819','SS-10398 · Residential correction','+$5.10']]):kind==='customers'?cards([['North Store Inc.','842 shipments · Shopify','$15,920 spend'],['Acme Parts Ltd.','604 shipments · WooCommerce','$12,404 spend']]):shipmentTable()}</section></div>`}
function checkout(){return `<section class="page"><div class="eyebrow">Create shipment / 03</div><h1>Review & purchase.</h1><div class="form-card"><h3>Purolator Ground</h3><p>Brampton, ON → Vancouver, BC</p><hr style="border:0;border-top:1px solid var(--line)"><div class="toolbar"><span>Shipping</span><strong>$18.42 CAD</strong></div><h3>Payment</h3><div class="notice">A saved, tokenized payment method will appear here once a payment processor is connected.</div><button class="primary" onclick="alert('Demo only — no payment was processed.')">Purchase label · $18.42</button></div></section>`}
function tracking(){return shell('tracking',`<div class="eyebrow">Tracking / Purchased Labels</div><div class="toolbar"><div><h1>Tracking</h1><span class="muted">Every purchased label, shipment status and delivery event.</span></div><button class="primary" data-route="quote">+ Ship</button></div><div class="kpis"><div class="kpi"><small>Labels / 30d</small><strong>128</strong></div><div class="kpi"><small>In transit</small><strong>19</strong></div><div class="kpi"><small>Delivered</small><strong>103</strong></div><div class="kpi"><small>Exceptions</small><strong>3</strong></div></div><div class="filterbar"><input placeholder="Search shipment, tracking, recipient or order"><select><option>All statuses</option><option>Label created</option><option>In transit</option><option>Out for delivery</option><option>Delivered</option><option>Exception</option></select><select><option>All carriers</option><option>Purolator</option><option>UPS</option><option>FedEx</option><option>GLS</option></select></div><div class="tracking-table"><div class="tracking-row tracking-head"><span>Shipment</span><span>Tracking</span><span>Recipient</span><span>Carrier / service</span><span>Purchased</span><span>Status</span><span>Total</span></div><button class="tracking-row" data-route="shipment-detail"><strong>SS-10482</strong><span>PRL-782901284</span><span>Alex Morgan<br><small>Vancouver, BC</small></span><span>Purolator<br><small>Ground</small></span><span>Oct 07<br><small>8:14 AM</small></span><span><b class="badge">In transit</b><small>Mississauga, ON · 9:22 AM</small></span><strong>$18.42</strong></button><button class="tracking-row" data-route="shipment-detail"><strong>SS-10481</strong><span>1Z84A921039</span><span>Jamie Lee<br><small>Montréal, QC</small></span><span>UPS<br><small>Standard</small></span><span>Oct 06<br><small>4:32 PM</small></span><span><b class="badge">Delivered</b><small>Oct 07 · 1:08 PM</small></span><strong>$16.90</strong></button><button class="tracking-row" data-route="shipment-detail"><strong>SS-10480</strong><span>78410293401</span><span>Sam Rivera<br><small>Calgary, AB</small></span><span>FedEx<br><small>Ground</small></span><span>Oct 06<br><small>11:05 AM</small></span><span><b class="badge exception">Exception</b><small>Weather delay</small></span><strong>$20.14</strong></button></div>`)}

function auth(kind){return `<section class="page"><div class="eyebrow">SigmaShip account</div><h1>${kind==='login'?'Welcome back.':'Start shipping.'}</h1><div class="form-card" style="max-width:520px"><div class="form-field"><label>Email</label><input type="email"></div><div class="form-field" style="margin-top:15px"><label>Password</label><input type="password"></div>${kind==='login'?'<p><a href="#forgot">Forgot password?</a></p>':''}<button class="primary" style="margin-top:20px" onclick="location.hash='${kind==='login'?'quote':'onboarding'}'">${kind==='login'?'Log in':'Create account'} →</button></div></section>`}
function render(){let r=location.hash.slice(1)||'home',routes={orders,products,'store-settings':storeSettings,'quick-quote':quickQuote,'saved-quotes':savedQuotes,addresses,packages,'carrier-accounts':carrierAccounts,'default-settings':defaultSettings,returns:returnsPage,pickups,team,settings,support,tickets,bulk,manifests,claims,reports,'store-detail':storeDetail,forgot,pricing,'order-detail':orderDetail,'shipment-detail':shipmentDetail,label:labelPage,invoices,transactions,notifications,profile,security,onboarding,admin,accounting},html=r.startsWith('admin-')?adminPage(r.slice(6)):r==='home'?home():r==='quote'?quote():r==='dashboard'?dashboard():r==='billing'?billing():r==='checkout'?checkout():r==='tracking'?tracking():r==='login'||r==='signup'?auth(r):routes[r]?routes[r]():simple(r,r[0].toUpperCase()+r.slice(1),'Manage your '+r+' in SigmaShip.');$('#app').innerHTML=html;if(r==='quote'){document.querySelectorAll('.address-card').forEach(card=>setRegions(card));document.querySelectorAll('.address-card input,.address-card select').forEach(el=>el.addEventListener('input',updateOverview));document.querySelectorAll('#package-card input,#package-card select,#customs-card input,#customs-card select').forEach(el=>el.addEventListener('input',refreshShipmentOverview));updateOverview();refreshShipmentOverview()}document.querySelectorAll('[data-route]').forEach(el=>el.onclick=()=>location.hash=el.dataset.route)}


/* Universal front-end interaction layer */
const SSKEY='sigmaship-demo-state-v2';
const ssDefault={addresses:[],packages:[],quotes:[],products:[],pickups:[],claims:[],tickets:[],paymentMethods:[{brand:'Visa',last4:'4242',expiry:'12/29',default:true}],profile:{company:'Demo Merchant Inc.',name:'Vasilios Karteros',email:'shipping@example.com',phone:'(905) 555-0188'},settings:{}};
function ssLoad(){try{return Object.assign({},ssDefault,JSON.parse(localStorage.getItem(SSKEY)||'{}'))}catch(e){return structuredClone(ssDefault)}}
function ssSave(patch){const next=Object.assign(ssLoad(),patch);localStorage.setItem(SSKEY,JSON.stringify(next));return next}
function ssToast(msg,type='ok'){document.querySelector('.ss-toast')?.remove();let x=document.createElement('div');x.className='ss-toast '+type;x.textContent=msg;document.body.appendChild(x);requestAnimationFrame(()=>x.classList.add('show'));setTimeout(()=>{x.classList.remove('show');setTimeout(()=>x.remove(),220)},2400)}
function ssModal(title,body,submit='Save',onSubmit){document.querySelector('.ss-modal')?.remove();let m=document.createElement('div');m.className='ss-modal';m.innerHTML=`<div class="ss-dialog"><div class="toolbar"><div><div class="eyebrow">SigmaShip</div><h2>${title}</h2></div><button class="ghost ss-close">Close</button></div><form class="ss-form">${body}<div class="ss-actions"><button type="button" class="ghost ss-cancel">Cancel</button><button type="submit" class="primary">${submit}</button></div></form></div>`;document.body.appendChild(m);let close=()=>m.remove();m.querySelector('.ss-close').onclick=close;m.querySelector('.ss-cancel').onclick=close;m.onclick=e=>{if(e.target===m)close()};m.querySelector('form').onsubmit=e=>{e.preventDefault();if(!e.currentTarget.reportValidity())return;onSubmit?.(Object.fromEntries(new FormData(e.currentTarget)));close()}}
function ssField(label,name,type='text',value='',extra=''){return `<div class="form-field"><label>${label}</label><input name="${name}" type="${type}" value="${value}" ${extra}></div>`}
function ssConfirm(msg,yes){if(confirm(msg))yes()}
function wireGenericButtons(){
 document.querySelectorAll('button').forEach(b=>{if(b.dataset.route||b.onclick||b.type==='submit'||b.dataset.wired)return;b.dataset.wired='1';let t=b.textContent.trim().toLowerCase();
  if(t.includes('export')) b.onclick=()=>downloadCSV('sigmaship-export.csv',[['Reference','Status','Amount'],['SS-10482','In transit','18.42'],['SS-10481','Delivered','16.90']]);
  else if(t.includes('download statement')) b.onclick=()=>downloadCSV('sigmaship-statement.csv',[['Invoice','Period','Amount'],['INV-2026-10','October 2026','2418.16']]);
  else if(t==='manage'||t==='view'||t.includes('review')) b.onclick=()=>ssToast('Detail view opened in the prototype.');
  else if(t.includes('save')) b.onclick=()=>{saveVisibleForm();ssToast('Changes saved.')};
 })}
function saveVisibleForm(){let data={};document.querySelectorAll('.portal-workspace input,.portal-workspace select,.portal-workspace textarea').forEach((el,i)=>{data[el.name||el.dataset.key||('field'+i)]=el.type==='checkbox'?el.checked:el.value});let s=ssLoad();s.settings=Object.assign({},s.settings,{[location.hash]:data});ssSave(s)}
function downloadCSV(name,rows){let csv=rows.map(r=>r.map(v=>'"'+String(v).replaceAll('"','""')+'"').join(',')).join('\n'),a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv'}));a.download=name;a.click();URL.revokeObjectURL(a.href);ssToast('Export downloaded.')}
function addAddress(){ssModal('Add address',`<div class="form-grid">${ssField('Contact name','name','text','','required')}${ssField('Company','company')}${ssField('Street address','address','text','','required')}${ssField('City','city','text','','required')}${ssField('Province / State','region','text','','required')}${ssField('Postal / ZIP','postal','text','','required')}${ssField('Country','country','text','Canada','required')}${ssField('Phone','phone','tel')}${ssField('Email','email','email')}</div>`,'Save address',d=>{let s=ssLoad();s.addresses.push(d);ssSave(s);ssToast('Address saved.');render()})}
function addPackage(){ssModal('New package preset',`<div class="form-grid">${ssField('Preset name','name','text','','required')}${ssField('Weight','weight','number','','required min="0" step=".01"')}${ssField('Length','length','number','','required min="0" step=".01"')}${ssField('Width','width','number','','required min="0" step=".01"')}${ssField('Height','height','number','','required min="0" step=".01"')}<div class="form-field"><label>Units</label><select name="units"><option>lb / in</option><option>kg / cm</option></select></div></div>`,'Save preset',d=>{let s=ssLoad();s.packages.push(d);ssSave(s);ssToast('Package preset saved.');render()})}
function addProduct(){ssModal('Add product',`<div class="form-grid">${ssField('Product name','name','text','','required')}${ssField('SKU','sku','text','','required')}${ssField('Weight (lb)','weight','number','','required min="0" step=".01"')}${ssField('HS code','hs')}${ssField('Country of origin','origin','text','Canada')}${ssField('Declared value','value','number','','min="0" step=".01"')}</div>`,'Add product',d=>{let s=ssLoad();s.products.push(d);ssSave(s);ssToast('Product added.');render()})}
function schedulePickup(){ssModal('Schedule pickup',`<div class="form-grid"><div class="form-field"><label>Carrier</label><select name="carrier"><option>Purolator</option><option>UPS</option><option>FedEx</option><option>GLS</option></select></div>${ssField('Pickup date','date','date','','required')}${ssField('Ready time','ready','time','','required')}${ssField('Close time','close','time','','required')}${ssField('Parcel count','parcels','number','1','required min="1"')}${ssField('Pickup address','address','text','14 Sigma Way, Brampton, ON','required')}</div>`,'Schedule pickup',d=>{let s=ssLoad();s.pickups.push(d);ssSave(s);ssToast('Pickup scheduled.');render()})}
function newClaim(){ssModal('New claim',`<div class="form-grid">${ssField('Shipment ID','shipment','text','','required')}<div class="form-field"><label>Claim type</label><select name="type"><option>Lost parcel</option><option>Damage</option><option>Service failure</option></select></div>${ssField('Claim amount','amount','number','','required min="0" step=".01"')}<div class="form-field full"><label>Description</label><textarea name="description" required placeholder="Tell us what happened"></textarea></div></div>`,'Submit claim',d=>{let s=ssLoad();s.claims.push(Object.assign({status:'Submitted'},d));ssSave(s);ssToast('Claim submitted.');render()})}
function newTicket(){ssModal('New support ticket',`<div class="form-grid"><div class="form-field"><label>Category</label><select name="category"><option>Shipping</option><option>Billing</option><option>Tracking</option><option>Store integration</option><option>Technical</option></select></div>${ssField('Subject','subject','text','','required')}<div class="form-field full"><label>Message</label><textarea name="message" required placeholder="How can we help?"></textarea></div></div>`,'Create ticket',d=>{let s=ssLoad();s.tickets.push(Object.assign({status:'Open'},d));ssSave(s);ssToast('Ticket created.');render()})}
function addPayment(){ssModal('Add payment method',`<div class="notice">Prototype only. Production card entry will be handled by a PCI-compliant hosted payment element; SigmaShip will never store raw card numbers or CVV.</div>${ssField('Name on card','name','text','','required')}${ssField('Demo last four digits','last4','text','','required maxlength="4" pattern="[0-9]{4}"')}${ssField('Expiry','expiry','text','','required placeholder="MM/YY"')}`,'Save payment method',d=>{let s=ssLoad();s.paymentMethods.push({brand:'Card',last4:d.last4,expiry:d.expiry,default:false});ssSave(s);ssToast('Payment method saved in demo state.')})}
function connectStore(){ssModal('Connect store',`<div class="form-field"><label>Platform</label><select name="platform"><option>Shopify</option><option>WooCommerce</option></select></div>${ssField('Store URL','url','url','','required placeholder="https://..."')}<div class="notice">Submitting this prototype form simulates starting OAuth. Production connection requires platform credentials and a secure backend.</div>`,'Continue',d=>ssToast(d.platform+' connection flow started.'))}
function inviteTeam(){ssModal('Invite team member',`${ssField('Email','email','email','','required')}<div class="form-field"><label>Role</label><select name="role"><option>Operator</option><option>Billing</option><option>Admin</option></select></div>`,'Send invite',d=>ssToast('Invitation sent to '+d.email+'.'))}
function wirePageActions(){
 let r=location.hash.slice(1);
 const map={
  addresses:[['+ add address',addAddress]],
  packages:[['+ new preset',addPackage]],
  products:[['+ add product',addProduct]],
  pickups:[['+ schedule pickup',schedulePickup]],
  claims:[['+ new claim',newClaim]],
  tickets:[['+ new ticket',newTicket]],
  accounting:[['+ add payment method',addPayment]],
  billing:[['+ add payment method',addPayment]],
  'store-settings':[['+ connect store',connectStore]],
  team:[['+ invite member',inviteTeam]]
 };
 (map[r]||[]).forEach(([label,fn])=>[...document.querySelectorAll('button')].filter(b=>b.textContent.trim().toLowerCase()===label).forEach(b=>b.onclick=fn));
 if(r==='forgot'){let b=[...document.querySelectorAll('button')].find(x=>x.textContent.includes('Send reset'));if(b)b.onclick=()=>{let e=document.querySelector('input[type=email]');if(!e?.value||!e.checkValidity()){e?.reportValidity();return}ssToast('Password reset link sent to '+e.value+'.')}}
 if(r==='login'||r==='signup'){let b=document.querySelector('.form-card .primary');if(b)b.onclick=()=>{let es=document.querySelectorAll('.form-card input');if([...es].some(x=>!x.value)){ssToast('Enter your email and password.','error');return}location.hash=r==='login'?'quote':'onboarding'}}
 if(r==='profile'){let b=[...document.querySelectorAll('button')].find(x=>x.textContent.includes('Save profile'));if(b)b.onclick=()=>{saveVisibleForm();ssToast('Profile saved.')}}
 if(r==='default-settings'||r==='notifications'){let b=[...document.querySelectorAll('button')].find(x=>x.textContent.toLowerCase().includes('save'));if(b)b.onclick=()=>{saveVisibleForm();ssToast('Defaults saved.')}}
 if(r==='store-settings'){document.querySelectorAll('.store-card button').forEach(b=>{if(b.textContent.trim()==='Connect')b.onclick=connectStore;if(b.textContent.trim()==='Manage')b.onclick=()=>location.hash='store-detail'})}
 if(r==='orders'){document.querySelectorAll('.table .row:not(.head)').forEach(row=>row.onclick=()=>location.hash='order-detail')}
 if(r==='checkout'){let b=document.querySelector('.primary');if(b)b.onclick=()=>{ssToast('Demo label purchased.');setTimeout(()=>location.hash='tracking',500)}}
 wireFilters();wireGenericButtons();
}
function wireFilters(){document.querySelectorAll('.filterbar input,.filterbar select').forEach(el=>el.addEventListener('input',()=>{let bar=el.closest('.filterbar'),q=(bar.querySelector('input')?.value||'').toLowerCase(),sels=[...bar.querySelectorAll('select')].map(x=>x.value.toLowerCase());let rows=document.querySelectorAll('.tracking-row:not(.tracking-head),.table .row:not(.head)');rows.forEach(row=>{let txt=row.textContent.toLowerCase(),ok=!q||txt.includes(q);sels.forEach(s=>{if(!s.startsWith('all ')&&!txt.includes(s))ok=false});row.style.display=ok?'':'none'})}))}

function saveQuickQuote(){let ins=[...document.querySelectorAll('.quick-quote-layout input')],sels=[...document.querySelectorAll('.quick-quote-layout select')];if(ins.length<5||!ins[0].value||!ins[1].value){ssToast('Enter origin and destination postal / ZIP codes.','error');return}let s=ssLoad();s.quotes.push({id:'SQ-'+String(2085+s.quotes.length),from:ins[0].value,to:ins[1].value,weight:ins[2]?.value||'',length:ins[3]?.value||'',width:ins[4]?.value||'',height:ins[5]?.value||'',package:sels[0]?.value||'Box',created:new Date().toISOString()});ssSave(s);ssToast('Quote saved.')}
function enhanceQuote(){
 let save=[...document.querySelectorAll('.quick-quote-layout button')].find(b=>b.textContent.includes('Save quote'));if(save)save.onclick=saveQuickQuote;
}
function enhanceAddresses(){if(location.hash!=='#addresses')return;let s=ssLoad();if(!s.addresses.length)return;let wrap=document.querySelector('.list-cards');s.addresses.forEach((a,i)=>{let d=document.createElement('div');d.className='card list-card';d.innerHTML=`<div><h3>${a.company||a.name}</h3><p class="muted">${a.address} · ${a.city}, ${a.region} ${a.postal}</p></div><strong>Saved</strong><button class="ghost">Delete</button>`;d.querySelector('button').onclick=()=>ssConfirm('Delete this address?',()=>{let n=ssLoad();n.addresses.splice(i,1);ssSave(n);render()});wrap?.appendChild(d)})}
function enhancePackages(){if(location.hash!=='#packages')return;let s=ssLoad();if(!s.packages.length)return;let wrap=document.querySelector('.list-cards');s.packages.forEach((p,i)=>{let d=document.createElement('div');d.className='card list-card';d.innerHTML=`<div><h3>${p.name}</h3><p class="muted">${p.length} × ${p.width} × ${p.height} · ${p.weight} · ${p.units}</p></div><strong>Custom</strong><button class="ghost">Delete</button>`;d.querySelector('button').onclick=()=>ssConfirm('Delete this package preset?',()=>{let n=ssLoad();n.packages.splice(i,1);ssSave(n);render()});wrap?.appendChild(d)})}
function enhanceProducts(){if(location.hash!=='#products')return;let s=ssLoad();let table=document.querySelector('.table');s.products.forEach(p=>{let d=document.createElement('div');d.className='row';d.innerHTML=`<strong>${p.name}</strong><span>${p.sku}</span><span>${p.weight} lb</span><span>${p.hs||'—'}</span><span>${p.origin||'—'}</span>`;table?.appendChild(d)})}
function enhancePickups(){if(location.hash!=='#pickups')return;let s=ssLoad();let wrap=document.querySelector('.list-cards');s.pickups.forEach(p=>{let d=document.createElement('div');d.className='card list-card';d.innerHTML=`<div><h3>${p.date} · ${p.ready}–${p.close}</h3><p class="muted">${p.carrier} · ${p.address}</p></div><strong>${p.parcels} parcels</strong><button class="ghost">Cancel</button>`;d.querySelector('button').onclick=()=>ssToast('Pickup cancelled in demo state.');wrap?.appendChild(d)})}
function enhanceClaims(){if(location.hash!=='#claims')return;let s=ssLoad();let wrap=document.querySelector('.list-cards');s.claims.forEach(x=>{let d=document.createElement('div');d.className='card list-card';d.innerHTML=`<div><h3>${x.shipment}</h3><p class="muted">${x.type} · ${x.amount}</p></div><strong>${x.status}</strong><button class="ghost">View</button>`;wrap?.appendChild(d)})}
function enhanceTickets(){if(location.hash!=='#tickets')return;let s=ssLoad(),table=document.querySelector('.table');s.tickets.forEach((x,i)=>{let d=document.createElement('div');d.className='row';d.innerHTML=`<strong>#T-${1100+i}</strong><span>${x.subject}</span><span>Just now</span><span class="badge">${x.status}</span><button class="small-btn">View</button>`;d.querySelector('button').onclick=()=>ssModal(x.subject,`<div class="notice">${x.message}</div><div class="form-field"><label>Reply</label><textarea name="reply" required></textarea></div>`,'Send reply',()=>ssToast('Reply added to ticket.'));table?.appendChild(d)})}
function wireShipPurchase(){
 if(location.hash!=='#quote')return;
 document.querySelectorAll('#ratebox button').forEach(b=>{if(b.textContent.toLowerCase().includes('select')||b.textContent.toLowerCase().includes('ship'))b.onclick=()=>location.hash='checkout'});
}
const oldShowRates=window.showRates;
window.showRates=()=>{oldShowRates();wireShipPurchase()}

const oldRender=render;
render=function(){oldRender();setTimeout(()=>{wirePageActions();enhanceQuote();enhanceAddresses();enhancePackages();enhanceProducts();enhancePickups();enhanceClaims();enhanceTickets();enhanceCarrierAccounts();wireShipPurchase()},0)}

addEventListener('hashchange',render);render();